import React, { useState } from 'react';
import { useOSStore } from '../store/useOSStore';

export default function BulletinWidget() {
  const [isGlitched, setIsGlitched] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');
  const [isMinimized, setIsMinimized] = useState(false);

  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);

  const triggerGlitch = () => {
    setIsGlitched(true);
    setStatusMessage('⚠️ PRISM CORRUPTION SPIKE DETECTED! SCANNING VEIL...');
    setTimeout(() => setIsGlitched(false), 1800);
  };

  const handleCheckIn = () => {
    addCredits(100);
    addXP(50);
    setStatusMessage('✅ Checked in at Cyacademy Bulletin Node! +100 Credits, +50 XP');
    setTimeout(() => setStatusMessage(''), 4000);
  };

  const handleSyncSquad = () => {
    setStatusMessage('⚡ Squad Synced: 4 Operatives Active on Mesh Network.');
    setTimeout(() => setStatusMessage(''), 4000);
  };

  return (
    <div
      className={`relative z-10 w-full max-w-4xl mx-auto rounded-2xl border-2 transition-all duration-300 y2k-panel-shadow backdrop-blur-xl select-none overflow-hidden ${
        isGlitched
          ? 'border-pink-500 bg-pink-950/80 filter invert contrast-200 hue-rotate-180 animate-pulse'
          : 'border-[#4DF3FF]/50 bg-slate-950/85 text-white'
      }`}
    >
      {/* Background Shimmer & Glyph Overlay */}
      <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/10 via-violet-500/10 to-pink-500/10 pointer-events-none" />

      {/* ------------------------------------------------------------------ */}
      {/* HEADER NODE BAR                                                    */}
      {/* ------------------------------------------------------------------ */}
      <div className="relative z-10 flex items-center justify-between border-b border-[#4DF3FF]/30 bg-black/50 px-4 py-2.5">
        <div className="flex items-center gap-2 font-bold text-cyan-300 tracking-wider text-xs">
          <span className="text-violet-400 animate-spin">✦</span>
          <span>CYACADEMY BULLETIN NODE</span>
        </div>

        {/* Status Pill */}
        <div className="flex items-center gap-3 text-[10px] font-mono text-white/80">
          <span>Time: <strong className="text-amber-300">Evening</strong></span>
          <span className="text-white/30">•</span>
          <span>Veil Status: <strong className={isGlitched ? 'text-pink-400 animate-bounce' : 'text-cyan-400'}>Flicker</strong></span>
          <span className="text-white/30">•</span>
          <span>House: <strong className="text-violet-300">Vector</strong></span>
          <span className="text-white/30">•</span>
          <span>Role: <strong className="text-pink-400">Anti</strong></span>
          <button
            onClick={() => setIsMinimized((prev) => !prev)}
            className="ml-2 px-1.5 py-0.5 rounded bg-white/10 hover:bg-white/20 text-xs"
            title={isMinimized ? 'Expand Widget' : 'Minimize Widget'}
          >
            {isMinimized ? '＋' : '−'}
          </button>
        </div>
      </div>

      {!isMinimized && (
        <div className="p-4 space-y-3">
          {statusMessage && (
            <div className="rounded-lg border border-amber-400/40 bg-amber-500/20 p-2 text-center text-[11px] font-bold text-amber-300">
              {statusMessage}
            </div>
          )}

          {/* ------------------------------------------------------------------ */}
          {/* 3-COLUMN GLASS PANEL GRID                                          */}
          {/* ------------------------------------------------------------------ */}
          <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
            {/* COLUMN 1: CAMPUS FEED */}
            <div className="flex flex-col space-y-2.5 rounded-xl border border-[#4DF3FF]/30 bg-white/10 p-3 backdrop-blur-md shadow-lg">
              <div className="flex items-center justify-between border-b border-cyan-400/20 pb-1 font-bold text-cyan-300 text-xs">
                <span>CAMPUS FEED</span>
                <span className="text-[9px] text-white/40">Glass Panel</span>
              </div>

              <div className="rounded-lg border border-cyan-500/20 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-cyan-300 text-[11px]">▣ Class Updates</div>
                <div className="text-white/80 text-[10px]">Syntax HW: Quantum Recursion</div>
                <div className="text-white/50 text-[9px]">Lab Open until 22:00</div>
              </div>

              <div className="rounded-lg border border-violet-500/20 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-violet-300 text-[11px]">▣ Clubs & Social</div>
                <div className="text-white/80 text-[10px]">Art Club 19:00</div>
                <div className="text-white/50 text-[9px]">Robotics Build</div>
              </div>

              <div className="rounded-lg border border-pink-500/20 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-pink-300 text-[11px]">▣ Pulse Trending</div>
                <div className="text-amber-300 font-mono text-[10px]">#DormDrama</div>
                <div className="text-cyan-300 font-mono text-[10px]">#OddSighting</div>
              </div>
            </div>

            {/* COLUMN 2: MISSIONS & OPS */}
            <div className="flex flex-col space-y-2.5 rounded-xl border border-[#C77CFF]/30 bg-white/10 p-3 backdrop-blur-md shadow-lg">
              <div className="flex items-center justify-between border-b border-violet-400/20 pb-1 font-bold text-violet-300 text-xs">
                <span>MISSIONS & OPS</span>
                <span className="text-[9px] text-pink-400">Glass Panel</span>
              </div>

              <div className="rounded-lg border border-red-500/30 bg-red-950/30 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-red-400 text-[11px]">▣ DGA Alerts</div>
                <div className="text-red-300 text-[10px]">Breach Alert: Sector 7</div>
                <div className="text-white/60 text-[9px]">Patrol Route Active</div>
              </div>

              <div className="rounded-lg border border-violet-500/20 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-violet-300 text-[11px]">▣ Career Tasks</div>
                <div className="text-white/80 text-[10px]">Faith Intake Clearance</div>
                <div className="text-white/50 text-[9px]">Archive Scan</div>
              </div>

              <div className="rounded-lg border border-pink-500/40 bg-pink-950/30 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-pink-400 text-[11px]">▣ PRISM Activity</div>
                <div className="text-pink-300 font-mono text-[10px]">Corruption ↑ 14.8%</div>
                <div className="text-white/50 text-[9px]">App Lockdown Active</div>
              </div>
            </div>

            {/* COLUMN 3: SIGNALS & LORE */}
            <div className="flex flex-col space-y-2.5 rounded-xl border border-[#FFD86B]/30 bg-white/10 p-3 backdrop-blur-md shadow-lg">
              <div className="flex items-center justify-between border-b border-amber-400/20 pb-1 font-bold text-amber-300 text-xs">
                <span>SIGNALS & LORE</span>
                <span className="text-[9px] text-amber-300">Glass Panel</span>
              </div>

              <div className="rounded-lg border border-amber-500/20 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-amber-300 text-[11px]">▣ City Anomalies</div>
                <div className="text-white/80 text-[10px]">Glassline Flicker</div>
                <div className="text-white/50 text-[9px]">Sub-Aureline Hum</div>
              </div>

              <div className="rounded-lg border border-cyan-500/20 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-cyan-300 text-[11px]">▣ Aethercore Echoes</div>
                <div className="text-cyan-200 font-mono text-[10px]">Fragment #07: "Protocol Unread"</div>
                <div className="rounded bg-black/70 p-1 font-mono text-pink-400 text-[9px] tracking-widest">
                  [ ████████████████ ]
                </div>
              </div>

              <div className="rounded-lg border border-amber-500/30 bg-black/50 p-2 space-y-0.5 text-xs">
                <div className="font-bold text-amber-400 text-[11px]">▣ Lineage Keys</div>
                <div className="text-amber-200 text-[10px]">Celestial Glyph</div>
                <div className="text-white/50 text-[9px]">"Seraphima Mark"</div>
              </div>
            </div>
          </div>

          {/* ------------------------------------------------------------------ */}
          {/* ACTION BUTTON FOOTER BAR                                           */}
          {/* ------------------------------------------------------------------ */}
          <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-white/20 bg-black/60 p-2">
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <button
                onClick={handleCheckIn}
                className="rounded-lg border border-emerald-500/40 bg-emerald-500/20 px-3 py-1 font-bold text-emerald-300 hover:bg-emerald-500/40 transition"
              >
                [ CHECK IN ]
              </button>
              <button
                onClick={handleSyncSquad}
                className="rounded-lg border border-cyan-500/40 bg-cyan-500/20 px-3 py-1 font-bold text-cyan-300 hover:bg-cyan-500/40 transition"
              >
                [ SYNC SQUAD ]
              </button>
              <button
                onClick={triggerGlitch}
                className="rounded-lg border border-pink-500/50 bg-pink-500/20 px-3 py-1 font-bold text-pink-300 hover:bg-pink-500/50 transition animate-pulse"
              >
                [ SCAN VEIL ]
              </button>
              <button
                onClick={() => {
                  setStatusMessage('📡 Pulse update shared to Cyacademy Mesh Network.');
                  setTimeout(() => setStatusMessage(''), 3000);
                }}
                className="rounded-lg border border-violet-500/40 bg-violet-500/20 px-3 py-1 font-bold text-violet-300 hover:bg-violet-500/40 transition"
              >
                [ PULSE SHARE ]
              </button>
            </div>

            <button
              onClick={() => {
                setStatusMessage('📜 Cyacademy Logs archived to miraverseDb.');
                setTimeout(() => setStatusMessage(''), 3000);
              }}
              className="rounded-lg border border-amber-500/40 bg-amber-500/20 px-3 py-1 font-bold text-amber-300 hover:bg-amber-500/40 transition text-xs"
            >
              [ ARCHIVE LOGS ]
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
